import{_ as e,o as s,c as i,a2 as a}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"Day 20: Bootloaders: U-Boot & Network Booting (TFTP/NFS)","description":"","frontmatter":{},"headers":[],"relativePath":"day20-uboot-tftp-nfs-booting.md","filePath":"day20-uboot-tftp-nfs-booting.md"}'),o={name:"day20-uboot-tftp-nfs-booting.md"};function n(h,t,l,r,p,d){return s(),i("div",null,[...t[0]||(t[0]=[a(`<h1 id="day-20-bootloaders-u-boot-network-booting-tftp-nfs" tabindex="-1">Day 20: Bootloaders: U-Boot &amp; Network Booting (TFTP/NFS) <a class="header-anchor" href="#day-20-bootloaders-u-boot-network-booting-tftp-nfs" aria-label="Permalink to &quot;Day 20: Bootloaders: U-Boot &amp; Network Booting (TFTP/NFS)&quot;">​</a></h1><div style="background:linear-gradient(135deg, #11998e 0%, #38ef7d 100%);padding:1.5rem;border-radius:12px;margin-bottom:2rem;color:white;"><p><strong>🎯 Learning Objectives</strong></p><p>By the end of this module, you will be able to:</p><ol><li>Explain the role of Das U-Boot and its environment variables</li><li>Stop the autoboot sequence to interact with the U-Boot command line</li><li>Configure a host PC to serve the Linux Kernel via TFTP</li><li>Configure a host PC to serve the Root Filesystem via NFS</li><li>Drastically reduce your compile-test-debug cycle time</li></ol></div><div class="info custom-block"><p class="custom-block-title">PREREQUISITES</p><ul><li>Completed <a href="/day19-kernel-configuration-menuconfig.html">Day 19: Kernel Configuration &amp; Fragments</a></li><li>A physical board (like the BeagleBone Black) connected via Ethernet to your host PC</li></ul></div><hr><h2 id="_1-the-u-boot-environment" tabindex="-1">1. The U-Boot Environment <a class="header-anchor" href="#_1-the-u-boot-environment" aria-label="Permalink to &quot;1. The U-Boot Environment&quot;">​</a></h2><p>In Day 3, we learned that U-Boot is the second stage of the bootloader. Its primary job is to initialize the RAM, load the kernel (<code>zImage</code>) and device tree (<code>.dtb</code>) into RAM, and then execute the kernel.</p><p>But how does U-Boot know <em>where</em> to load the kernel from? Does it look on the SD card? The eMMC chip? Over the network?</p><p>It decides this by reading its <strong>Environment Variables</strong>.</p><p>When you power on your board with a serial console connected, you will see a countdown: <code>Hit any key to stop autoboot: 3</code></p><p>If you press a key before the timer hits 0, you drop into the U-Boot command prompt (<code>=&gt;</code>). From here, you can print the environment variables:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">printenv</span></span></code></pre></div><h3 id="the-bootcmd-variable" tabindex="-1">The <code>bootcmd</code> Variable <a class="header-anchor" href="#the-bootcmd-variable" aria-label="Permalink to &quot;The \`bootcmd\` Variable&quot;">​</a></h3><p>The most important variable is <code>bootcmd</code>. When the autoboot timer hits 0, U-Boot simply executes whatever script is stored inside <code>bootcmd</code>.</p><p>A typical <code>bootcmd</code> for an SD card looks like this:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bootcmd</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">fatload</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> mmc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 0:1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0x82000000</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zImage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fatload</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mmc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 0:1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0x88000000</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> am335x-boneblack.dtb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bootz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0x82000000</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0x88000000</span></span></code></pre></div><p><em>(Translation: Load the kernel from the SD card&#39;s FAT partition to RAM address 0x82M, load the DTB to 0x88M, then boot them.)</em></p><hr><h2 id="_2-the-flashing-bottleneck" tabindex="-1">2. The Flashing Bottleneck <a class="header-anchor" href="#_2-the-flashing-bottleneck" aria-label="Permalink to &quot;2. The Flashing Bottleneck&quot;">​</a></h2><p>During development, you will modify your Yocto image frequently (adding new C apps, tuning the kernel, etc.).</p><p>The standard workflow is painful:</p><ol><li>Run <code>bitbake core-image-minimal</code> (takes a few minutes)</li><li>Eject SD card from PC, insert into Board.</li><li>Boot the board and test the changes.</li><li>Discover a bug.</li><li>Unplug the board, remove SD card, insert into PC.</li><li>Flash <code>.wic</code> image to SD card with <code>dd</code> (Takes 5-10 minutes!).</li><li>Repeat.</li></ol><p>This cycle ruins developer productivity. The solution is <strong>Network Booting</strong>.</p><hr><h2 id="_3-tftp-loading-the-kernel-over-ethernet" tabindex="-1">3. TFTP: Loading the Kernel over Ethernet <a class="header-anchor" href="#_3-tftp-loading-the-kernel-over-ethernet" aria-label="Permalink to &quot;3. TFTP: Loading the Kernel over Ethernet&quot;">​</a></h2><p>Instead of storing the <code>zImage</code> and <code>.dtb</code> on the SD card, you can store them on your Host PC. U-Boot can fetch them over the Ethernet cable using the TFTP (Trivial File Transfer Protocol) in a matter of seconds.</p><h3 id="step-1-set-up-tftp-on-your-ubuntu-host" tabindex="-1">Step 1: Set up TFTP on your Ubuntu Host <a class="header-anchor" href="#step-1-set-up-tftp-on-your-ubuntu-host" aria-label="Permalink to &quot;Step 1: Set up TFTP on your Ubuntu Host&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tftpd-hpa</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># The default directory is /srv/tftp</span></span></code></pre></div><h3 id="step-2-copy-your-yocto-outputs-to-the-tftp-folder" tabindex="-1">Step 2: Copy your Yocto outputs to the TFTP folder <a class="header-anchor" href="#step-2-copy-your-yocto-outputs-to-the-tftp-folder" aria-label="Permalink to &quot;Step 2: Copy your Yocto outputs to the TFTP folder&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/tmp/deploy/images/beaglebone/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zImage</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /srv/tftp/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> am335x-boneblack.dtb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /srv/tftp/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 777</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /srv/tftp/</span></span></code></pre></div><h3 id="step-3-tell-u-boot-to-fetch-from-the-network" tabindex="-1">Step 3: Tell U-Boot to fetch from the Network <a class="header-anchor" href="#step-3-tell-u-boot-to-fetch-from-the-network" aria-label="Permalink to &quot;Step 3: Tell U-Boot to fetch from the Network&quot;">​</a></h3><p>Stop the autoboot on your board and set the network IPs (assuming your PC is <code>192.168.1.100</code> and the board is <code>192.168.1.50</code>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">setenv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ipaddr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.1.50</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">setenv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serverip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.1.100</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">tftp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0x82000000</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zImage</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">tftp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0x88000000</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> am335x-boneblack.dtb</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">bootz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0x82000000</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0x88000000</span></span></code></pre></div><p><em>The kernel will now boot over the network in seconds!</em></p><hr><h2 id="_4-nfs-mounting-the-rootfs-over-ethernet" tabindex="-1">4. NFS: Mounting the Rootfs over Ethernet <a class="header-anchor" href="#_4-nfs-mounting-the-rootfs-over-ethernet" aria-label="Permalink to &quot;4. NFS: Mounting the Rootfs over Ethernet&quot;">​</a></h2><p>TFTP solves the kernel bottleneck, but what about the root filesystem containing your C applications?</p><p>You can extract your rootfs to a folder on your Host PC and export that folder over the network using NFS (Network File System). When the kernel boots on the board, instead of mounting <code>/dev/mmcblk0p2</code> (the SD card), it mounts the folder on your host PC!</p><p>If you modify a C file in Yocto, run <code>make</code>, and copy the binary into the NFS folder, it immediately appears on the board without rebooting!</p><h3 id="step-1-set-up-nfs-on-your-ubuntu-host" tabindex="-1">Step 1: Set up NFS on your Ubuntu Host <a class="header-anchor" href="#step-1-set-up-nfs-on-your-ubuntu-host" aria-label="Permalink to &quot;Step 1: Set up NFS on your Ubuntu Host&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nfs-kernel-server</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /srv/nfs/beaglebone</span></span></code></pre></div><h3 id="step-2-extract-the-rootfs" tabindex="-1">Step 2: Extract the Rootfs <a class="header-anchor" href="#step-2-extract-the-rootfs" aria-label="Permalink to &quot;Step 2: Extract the Rootfs&quot;">​</a></h3><p>Yocto generates a <code>.tar.bz2</code> of the rootfs for exactly this purpose.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -xf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/tmp/deploy/images/beaglebone/core-image-minimal-beaglebone.tar.bz2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /srv/nfs/beaglebone</span></span></code></pre></div><h3 id="step-3-export-the-folder" tabindex="-1">Step 3: Export the folder <a class="header-anchor" href="#step-3-export-the-folder" aria-label="Permalink to &quot;Step 3: Export the folder&quot;">​</a></h3><p>Edit <code>/etc/exports</code> on your host PC and add:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/srv/nfs/beaglebone *(rw,sync,no_root_squash,no_subtree_check)</span></span></code></pre></div><p>Restart the server: <code>sudo systemctl restart nfs-kernel-server</code></p><h3 id="step-4-tell-the-kernel-to-mount-nfs" tabindex="-1">Step 4: Tell the Kernel to mount NFS <a class="header-anchor" href="#step-4-tell-the-kernel-to-mount-nfs" aria-label="Permalink to &quot;Step 4: Tell the Kernel to mount NFS&quot;">​</a></h3><p>You tell the kernel where its root filesystem is by modifying the <code>bootargs</code> variable in U-Boot.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">setenv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bootargs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;console=ttyO0,115200n8 root=/dev/nfs nfsroot=192.168.1.100:/srv/nfs/beaglebone,v3,tcp rw ip=192.168.1.50&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">bootz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0x82000000</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0x88000000</span></span></code></pre></div><hr><h2 id="_5-hands-on-lab-exercises" tabindex="-1">5. Hands-On Lab Exercises <a class="header-anchor" href="#_5-hands-on-lab-exercises" aria-label="Permalink to &quot;5. Hands-On Lab Exercises&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">LAB 20.1: Exploring U-Boot</p><ol><li>Connect to your board via the Serial Console.</li><li>Power cycle the board and hit the Spacebar to stop autoboot.</li><li>Run <code>printenv</code>. Look at the sheer volume of variables.</li><li>Try to trace the execution path. Find <code>bootcmd</code>. What script does it run? Find that script. What does it run?</li></ol></div><hr><h2 id="_6-further-reading" tabindex="-1">6. Further Reading <a class="header-anchor" href="#_6-further-reading" aria-label="Permalink to &quot;6. Further Reading&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>URL</th></tr></thead><tbody><tr><td>U-Boot Network Booting</td><td><a href="https://docs.u-boot.org/en/latest/usage/netboot.html" target="_blank" rel="noreferrer">docs.u-boot.org/en/latest/usage/netboot.html</a></td></tr><tr><td>Kernel NFS Root Documentation</td><td><a href="https://www.kernel.org/doc/Documentation/filesystems/nfs/nfsroot.txt" target="_blank" rel="noreferrer">kernel.org/doc/Documentation/filesystems/nfs/nfsroot.txt</a></td></tr></tbody></table><hr><div style="display:flex;justify-content:space-between;margin-top:2rem;padding-top:1rem;border-top:1px solid #e2e8f0;"><a href="/day19-kernel-configuration-menuconfig">← Day 19: Kernel Configuration</a><a href="/day21-init-systems-and-systemd">Day 21: Init Systems &amp; Systemd →</a></div>`,58)])])}const g=e(o,[["render",n]]);export{c as __pageData,g as default};
